sys_script_include.script:
var AESAnnouncementExtension = Class.create();
AESAnnouncementExtension.prototype = {
    initialize: function() {},

    transformAnnouncement: function(announcement, gr, options) {

        announcement.extension_test = {
            number: announcement.number,
            category_count: announcement.categories.length,
            action_count: announcement.actions.length,
            tracking_available: announcement.tracking !== null
        };

        return announcement;
    },

    type: 'AESAnnouncementExtension'
};
